llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Artesunate, an artemisinin-derived lactone natural product, achieved 61% absolute oral bioavailability in Thai patients, demonstrating that plant-derived polycyclic lactones can exceed the 20% threshold despite solubility limitations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Idarubicin had a measured absolute oral bioavailability of 29.1% ± 3.8% in patients, providing direct evidence that a complex, poorly soluble natural product can have F clearly above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Gitoxin showed 96% absolute oral bioavailability in fasting volunteers, supporting that rigid, lipophilic, non-ionizable natural-product scaffolds can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Artemisinin, the closest structural family analogue, is reported to have low oral bioavailability in healthy volunteers and patients, which is the main evidence arguing for F below 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a triptolide-like diterpenoid triepoxide with multiple lactones, no ionizable groups, and a rigid lipophilic scaffold. Although the closest analogue artemisinin is often described as having low oral bioavailability, absolute F values for related lactone natural products (artesunate 61%, idarubicin ~29%, gitoxin 96%) support F ≥ 20%. The negative amphotericin/baicalin evidence is structurally too distant to override. Overall, the balance favors high oral bioavailability at the 20% threshold.",
  "evidence_gaps": [
    "No direct experimental absolute oral bioavailability measurement for the query molecule itself.",
    "All retrieved evidence molecules have low Morgan similarity (<0.2), limiting direct transferability.",
    "Artemisinin records are internally conflicting, with some reporting low/poor bioavailability and others reporting good or high absolute F values."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

